import { MakeLogicType, afterMount, connect, kea, key, path, props } from 'kea'
import { loaders } from 'kea-loaders'

import { FEATURE_FLAGS } from 'lib/constants'
import { FeatureFlagsSet, featureFlagLogic } from 'lib/logic/featureFlagLogic'
import { teamLogic } from 'scenes/teamLogic'

import * as api from '../generated/api'
import type { TaggerApi } from '../generated/api.schemas'

export interface ReplacedTaggerLogicProps {
    evaluationId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface replacedTaggerLogicValues {
    currentTeamId: number | null // teamLogic
    featureFlags: FeatureFlagsSet // featureFlagLogic
    replacedTagger: TaggerApi | null
    replacedTaggerLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface replacedTaggerLogicActions {
    loadReplacedTagger: () => any
    loadReplacedTaggerFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadReplacedTaggerSuccess: (
        replacedTagger: TaggerApi | null,
        payload?: any
    ) => {
        replacedTagger: TaggerApi | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface replacedTaggerLogicMeta {
    key: string
}

export type replacedTaggerLogicType = MakeLogicType<
    replacedTaggerLogicValues,
    replacedTaggerLogicActions,
    ReplacedTaggerLogicProps,
    replacedTaggerLogicMeta
>

export const replacedTaggerLogic = kea<replacedTaggerLogicType>([
    props({} as ReplacedTaggerLogicProps),
    key((props) => props.evaluationId),
    path((key) => ['products', 'ai_observability', 'evaluations', 'replacedTaggerLogic', key]),
    connect(() => ({ values: [teamLogic, ['currentTeamId'], featureFlagLogic, ['featureFlags']] })),

    loaders(({ props, values }) => ({
        replacedTagger: [
            null as TaggerApi | null,
            {
                loadReplacedTagger: async () => {
                    const response = await api.taggersList(String(values.currentTeamId), {
                        migrated_to_evaluation_id: props.evaluationId,
                        limit: 1,
                    })
                    return response.results[0] ?? null
                },
            },
        ],
    })),

    afterMount(({ actions, values }) => {
        // Only projects that had taggers can have one that became this evaluation, and the taggers API is closed to
        // the rest.
        if (values.featureFlags[FEATURE_FLAGS.LLM_ANALYTICS_TAGS]) {
            actions.loadReplacedTagger()
        }
    }),
])
